document.addEventListener("click",event=>{if(!state.opened)return;if(event.target.closest?.("#adminDebtDiagnosticClose")){closeDebtDiagnostic();return;}if(event.target.closest?.("#adminDebtDiagnosticCopy")){copyDebtDiagnostic();return;}const paymentMethod=event.target.closest?.("#adminDebtPaymentMethodField button[data-debt-payment-method]");if(paymentMethod){event.preventDefault();setDebtPaymentMethod(paymentMethod.dataset.debtPaymentMethod);return;}if(event.target.closest?.("#adminDebtReceiptBtn")){event.preventDefault();const input=$("driverDebtReceiptInput");if(!input)return;try{if(typeof input.showPicker==="function")input.showPicker();else input.click();}catch(_){input.click();}return;}if(event.target.closest?.("#adminDebtReceiptPreviewRemove")){event.preventDefault();clearReceipt();return;}const operation=event.target.closest?.(".admin-debt-operation-picker button[data-debt-operation]");if(operation){event.preventDefault();setDebtOperation(operation.dataset.debtOperation,{clear:true});return;}});
document.addEventListener("input",event=>{if(!state.opened)return;if(event.target?.id==="adminDebtAmount"){event.target.value=formatAmount(event.target.value);updateDebtSummary();}else if(event.target?.id==="adminDebtDescription")updateDebtSummary();});
document.addEventListener("change",event=>{if(!state.opened)return;if(event.target?.id==="adminDebtDriver"){state.billingRequestToken+=1;state.billingLoadingUid="";updateDebtSummary();if(state.operation==="payment"&&clean(event.target.value))void refreshSelectedBillingBalance({force:true}).catch(error=>console.warn("ADMIN_BILLING_BALANCE_READ",error?.code||error?.message||error));}if(event.target?.id==="driverDebtReceiptInput")selectReceipt(event.target.files?.[0]);});
document.addEventListener("submit",event=>{if(event.target?.id==="adminDebtForm")submitDriverDebt(event);});

